from lib import *
L = lambda *a, **k: lesson(4, "A0", *a, **k)
L(1, "Мої речі", "Назвати речі, які завжди з вами.",
 "Про одну річ кажуть із a або з my: a key, my key. Обидва слова разом не ставлять. Фрази ті самі, що й раніше: This is my phone. I have a ticket.",
 [W("phone", "/fəʊn/", "noun", "телефон", "This is my phone.", "Це мій телефон."),
  W("key", "/kiː/", "noun", "ключ", "I have a key.", "У мене є ключ."),
  W("bag", "/bæɡ/", "noun", "сумка", "This is my bag.", "Це моя сумка."),
  W("book", "/bʊk/", "noun", "книжка", "I have a book.", "У мене є книжка."),
  W("pen", "/pen/", "noun", "ручка", "Can I have a pen, please?", "Можна мені ручку, будь ласка?"),
  W("wallet", "/ˈwɒlɪt/", "noun", "гаманець", "This is my wallet.", "Це мій гаманець."),
  W("passport", "/ˈpɑːspɔːt/", "noun", "паспорт", "Here is my passport.", "Ось мій паспорт."),
  W("ticket", "/ˈtɪkɪt/", "noun", "квиток", "I have a ticket.", "У мене є квиток.")],
 [fb("She's ___ teacher.", ["a", "my", "not"], "Перед професією — a.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("phone", "телефон"), ("key", "ключ"), ("bag", "сумка"), ("book", "книжка")], "Phone пишеться через ph, а читається як «ф»."),
  mt([("pen", "ручка"), ("wallet", "гаманець"), ("passport", "паспорт"), ("ticket", "квиток")], "Passport і ticket знадобляться в кожній подорожі."),
  liu("Can I have a pen, please?", "Прослухайте. Що просить людина?", ["Ручку", "Ключ", "Квиток"], "A pen — ручка."),
  mc("Як правильно сказати «мій ключ»?", ["my key", "a my key", "my a key"], "My і a разом не вживають: або my key, або a key."),
  fb("This is my ___. I pay by card.", ["wallet", "book", "key"], "Картку тримають у гаманці — wallet."),
  bs("У мене є квиток.", ["I", "have", "a", "ticket"], ["is", "my"], "I have a ticket."),
  liu("Your passport, please.", "Вас просять про це в аеропорту. Що треба показати?", ["Паспорт", "Квиток", "Телефон"], "Your passport, please — «ваш паспорт, будь ласка»."),
  tr("Це моя сумка.", ["This is my bag"], "This is my bag."),
  li("Your ticket, please.", "Ви подаєте квиток. Що сказати?", ["Here you are.", "Excuse me.", "That's all."], "Коли щось подають, кажуть Here you are.")])
L(2, "Що це?", "Спитати, що це, і назвати речі в кімнаті.",
 "This — про те, що поруч, that — про те, що далі. What's this? — «Що це?». Відповідь починається з It's: It's a table. It's — скорочення від it is.",
 [W("that", "/ðæt/", "pronoun", "те, той (далі від вас)", "What's that?", "Що то?"),
  W("room", "/ruːm/", "noun", "кімната", "This is my room.", "Це моя кімната."),
  W("table", "/ˈteɪbl/", "noun", "стіл", "It's a table.", "Це стіл."),
  W("chair", "/tʃeə/", "noun", "стілець", "It's a chair.", "Це стілець."),
  W("bed", "/bed/", "noun", "ліжко", "It's a large bed.", "Це велике ліжко."),
  W("door", "/dɔː/", "noun", "двері", "That's the door.", "То двері."),
  W("window", "/ˈwɪndəʊ/", "noun", "вікно", "It's a small window.", "Це мале вікно.")],
 [fb("I have a ___. I'm from Ukraine.", ["passport", "pen", "chair"], "Паспорт показує, звідки ви.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("table", "стіл"), ("chair", "стілець"), ("bed", "ліжко"), ("room", "кімната")], "Меблі й сама кімната."),
  mt([("door", "двері"), ("window", "вікно"), ("this", "це (поруч)"), ("that", "те (далі)")], "This — близько, that — далеко."),
  liu("What's this?", "Прослухайте. Що вас питають?", ["Що це?", "Хто це?", "Де це?"], "What — що. What's this? — «Що це?»"),
  fb("What's this? ___ a key.", ["It's", "He's", "I'm"], "Про річ кажуть it: It's a key."),
  mc("Річ лежить далеко від вас. Як спитати?", ["What's that?", "What's this?", "Who's that?"], "Далеко — that. Who питає про людину."),
  liu("It's a large room.", "Прослухайте. Що каже людина?", ["Це велика кімната", "Це мала кімната", "Це велике ліжко"], "Large — велика, room — кімната."),
  bs("Це мале вікно.", ["It's", "a", "small", "window"], ["that", "large"], "It's a small window: слово small стоїть перед window."),
  tr("Що це?", ["What's this", "What is this"], "What's this?"),
  li("What's that?", "Вам показують на двері. Що відповісти?", ["It's a door.", "He's a door.", "This is my door, thanks."], "Про річ: It's a…")])
L(3, "Де мій телефон?", "Спитати, де річ, і сказати, де вона лежить.",
 "Where is…? — «Де…?»: Where is my phone? Місце називають маленькими словами: on — на, in — у, under — під, next to — біля. It's on the table. Якщо не знаєте — I don't know.",
 [W("on", "/ɒn/", "preposition", "на", "It's on the table.", "Він на столі."),
  W("under", "/ˈʌndə/", "preposition", "під", "It's under the bed.", "Воно під ліжком."),
  W("next to", "/ˈnekst tuː/", "preposition", "біля, поруч із", "It's next to the door.", "Воно біля дверей."),
  W("there", "/ðeə/", "adverb", "там", "It's there.", "Воно там."),
  W("car", "/kɑː/", "noun", "машина", "It's in the car.", "Воно в машині."),
  W("floor", "/flɔː/", "noun", "підлога", "It's on the floor.", "Воно на підлозі."),
  W("pocket", "/ˈpɒkɪt/", "noun", "кишеня", "It's in my pocket.", "Він у моїй кишені."),
  W("I don't know", "/aɪ ˌdəʊnt ˈnəʊ/", "phrase", "я не знаю", "I don't know.", "Я не знаю.")],
 [li("What's this?", "Повторимо. Вам показують стілець. Що відповісти?", ["It's a chair.", "It's a table.", "He's a chair."], "Chair — стілець."),
  mt([("on", "на"), ("under", "під"), ("next to", "біля"), ("in", "у")], "Чотири слова, якими описують місце."),
  mt([("car", "машина"), ("floor", "підлога"), ("pocket", "кишеня"), ("there", "там")], "Here — тут, there — там."),
  liu("Where is my phone?", "Прослухайте. Що шукає людина?", ["Телефон", "Ключ", "Гаманець"], "Where is my phone? — «Де мій телефон?»"),
  fb("The book is ___ the table.", ["on", "how", "there"], "«На столі» — on the table."),
  fb("My wallet is ___ my bag.", ["in", "on", "next"], "Усередині — in: in my bag."),
  liu("It's under the bed.", "Прослухайте. Де лежить річ?", ["Під ліжком", "На ліжку", "Біля ліжка"], "Under — під."),
  bs("Він у моїй кишені.", ["It's", "in", "my", "pocket"], ["on", "the"], "It's in my pocket."),
  tr("Де мій ключ?", ["Where is my key", "Where's my key"], "Where is my key?"),
  li("Where is the car?", "Ви не знаєте, де машина. Що відповісти?", ["I don't know.", "It's a car.", "Yes, please."], "Не знаєте — I don't know.")])
L(4, "Один і багато", "Говорити про кілька речей і спитати, скільки їх.",
 "Коли речей більше однієї, до слова додають -s: a key — two keys. Замість this кажуть these, замість that — those, і замість is — are: These are my keys. How many…? — «Скільки…?»",
 [W("these", "/ðiːz/", "pronoun", "ці (поруч)", "These are my keys.", "Це мої ключі."),
  W("those", "/ðəʊz/", "pronoun", "ті (далі)", "Those are my bags.", "То мої сумки."),
  W("how many", "/ˌhaʊ ˈmeni/", "phrase", "скільки (штук)", "How many bags?", "Скільки сумок?"),
  W("glasses", "/ˈɡlɑːsɪz/", "noun", "окуляри", "Where are my glasses?", "Де мої окуляри?"),
  W("shoes", "/ʃuːz/", "noun", "взуття, черевики", "These are my shoes.", "Це моє взуття."),
  W("photo", "/ˈfəʊtəʊ/", "noun", "фото", "I have two photos.", "У мене є два фото.")],
 [fb("My phone is ___ the table.", ["on", "how", "these"], "«На столі» — on the table.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("these", "ці"), ("those", "ті"), ("how many", "скільки"), ("photo", "фото")], "This — these, that — those."),
  mc("Як сказати «три квитки»?", ["three tickets", "three ticket", "tickets three"], "Більше одного — додаємо -s."),
  fb("These ___ my shoes.", ["are", "is", "am"], "З these і those стоїть are."),
  fb("___ are my glasses.", ["These", "This", "It"], "Окуляри — завжди множина, тому these."),
  liu("How many bags?", "Прослухайте. Що вас питають в аеропорту?", ["Скільки сумок?", "Де сумки?", "Чиї це сумки?"], "How many — скільки."),
  liu("I have two bags and four books.", "Прослухайте. Що є в людини?", ["2 сумки й 4 книжки", "4 сумки й 2 книжки", "2 сумки й 5 книжок"], "Two bags, four books."),
  bs("Це мої ключі.", ["These", "are", "my", "keys"], ["is", "this"], "These are my keys."),
  tr("Де мої окуляри?", ["Where are my glasses"], "Where are my glasses? З множиною — are."),
  li("How many children do you have?", "У вас двоє дітей. Що відповісти?", ["I have two children.", "I have two child.", "I'm two children."], "Two children — множина від child.")])
L(5, "Який він?", "Описати річ: нова чи стара, велика, гарна, дорога чи дешева.",
 "Слово, що описує, стоїть перед річчю: a new phone. Або після is: My phone is new. Very — «дуже»: very big. But — «але»: It's nice but expensive.",
 [W("new", "/njuː/", "adjective", "новий", "It's a new phone.", "Це новий телефон."),
  W("big", "/bɪɡ/", "adjective", "великий", "It's a big room.", "Це велика кімната."),
  W("bad", "/bæd/", "adjective", "поганий", "It's a bad photo.", "Це погане фото."),
  W("beautiful", "/ˈbjuːtɪfl/", "adjective", "гарний, красивий", "It's a beautiful room.", "Це гарна кімната."),
  W("cheap", "/tʃiːp/", "adjective", "дешевий", "The ticket is cheap.", "Квиток дешевий."),
  W("expensive", "/ɪkˈspensɪv/", "adjective", "дорогий", "The phone is expensive.", "Телефон дорогий."),
  W("very", "/ˈveri/", "adverb", "дуже", "It's very good.", "Це дуже добре."),
  W("but", "/bʌt/", "conjunction", "але", "It's nice but expensive.", "Воно гарне, але дороге.")],
 [fb("These ___ my books.", ["are", "is", "but"], "З these — are.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("new", "новий"), ("big", "великий"), ("bad", "поганий"), ("beautiful", "гарний")], "Big і large означають те саме — «великий»."),
  mt([("cheap", "дешевий"), ("expensive", "дорогий"), ("very", "дуже"), ("but", "але")], "Cheap і expensive — протилежні слова."),
  mc("Як сказати «новий телефон»?", ["a new phone", "a phone new", "new a phone"], "Порядок: a + яке + що."),
  fb("My car is ___ old.", ["very", "but", "a"], "Very old — дуже стара."),
  fb("The room is small ___ beautiful.", ["but", "very", "or"], "But — «але»: мала, але гарна."),
  liu("It's very expensive.", "Прослухайте. Що каже людина про ціну?", ["Це дуже дорого", "Це дуже дешево", "Це недорого"], "Expensive — дорогий."),
  bs("Моя сумка дуже велика.", ["My", "bag", "is", "very", "big"], ["but", "a"], "My bag is very big."),
  tr("Це гарне фото.", ["It's a beautiful photo", "It is a beautiful photo", "This is a beautiful photo"], "It's a beautiful photo."),
  li("How much is it? — It's fifty pounds.", "Ви вважаєте, що це дорого. Що сказати?", ["It's very expensive.", "It's very cheap.", "It's very new."], "Дорого — expensive.")])
L(6, "Повторення: мої речі", "Назвати свої речі, сказати, де вони, і описати їх.",
 "Нових слів немає. Повторюємо весь розділ: This is…, These are…, What's this?, Where is…?, on / in / under / next to, How many…?, new, big, expensive.",
 [],
 [li("Where is your passport?", "Паспорт у вашій сумці. Що відповісти?", ["It's in my bag.", "It's on my bag.", "These are in my bag."], "Усередині сумки — in my bag."),
  bs("Це мої ключі.", ["These", "are", "my", "keys"], ["is", "those"], "These are my keys."),
  fb("What's that? ___ a window.", ["It's", "These", "He's"], "Про одну річ — It's."),
  tr("Де мій телефон?", ["Where is my phone", "Where's my phone"], "Where is my phone?"),
  fb("My wallet is ___ the table, next to the book.", ["on", "how", "many"], "На столі — on the table."),
  liu("How many tickets?", "Прослухайте. Що вас питають?", ["Скільки квитків?", "Де квитки?", "Скільки коштує квиток?"], "How many — скільки штук. How much — скільки коштує."),
  mc("Як сказати «У мене новий телефон»?", ["I have a new phone.", "I have a phone new.", "I'm a new phone."], "I have a new phone."),
  tr("Моя кімната мала, але гарна.", ["My room is small but beautiful", "My room is small but nice"], "My room is small but beautiful."),
  liu("The shoes are under the bed.", "Прослухайте. Де взуття?", ["Під ліжком", "На ліжку", "Біля дверей"], "Under the bed — під ліжком."),
  li("Where are my glasses?", "Окуляри лежать на столі. Що відповісти?", ["On the table.", "It's a table.", "I have a table."], "Досить короткої відповіді з місцем: On the table.")],
 review=True)
